const log = createLogger('VariantGenerationService');
const MAX_RELEVANT_FILES = 12;

export type StaticPreviewWorkItemRunner = {
  runWorkItems: (args: {
    sessionId: string;
    workItemIds: string[];
  }) => Promise<{ succeeded: number; failed: number }>;
};

export type VariantGenerationServiceOptions = {
  recordGuidance?: (args: {
    request: ChangeRequest;
    workItemIds: string[];
  }) => Promise<void> | void;
  bridge: SessionBridgeService;
  storage?: ProjectStorage;
  onGeneratedProject?: (projectPath: string) => Promise<void>;
  orchestrator: AgentVariantsOrchestrator;
  staticPreviewRunner?: StaticPreviewWorkItemRunner;
  projectPath?: string;
  staticEntry?: string;
  createSessionId?: () => string;
  executor?: WorkerExecutorService;
  browserAgent?: Pick<BrowserAgentClient, 'captureDesignEvidence'>;
};

export type VariantRequestResult = {
  guidanceWarning?: GuidanceWarning;
  guidance?: Array<Pick<GuidanceDocument, 'id' | 'title'>>;
  profileContext?: import('../types/design-profile').ProfileContextResult;
  success: boolean;
  error?: string;
};

const hasWhitespace = (value: string): boolean => /\s/.test(value);

const deriveTarget = (element: ElementRef, staticEntry?: string): Target => {
  if (staticEntry) {
    return { type: 'file', ref: staticEntry };
  }
  const filePaths = element.filePaths ?? [];
  if (filePaths.length === 1) {
    return { type: 'file', ref: filePaths[0] };
  }
  if (element.rivetId) {
    return {
      type: 'element',
      ref: `[data-rivet-id="${element.rivetId}"]`,
    };
  }
  if (element.id && !hasWhitespace(element.id)) {
    return { type: 'element', ref: `#${element.id}` };
  }
  if (element.xpath) {
    return { type: 'element', ref: element.xpath };
  }
  const classTokens = element.className.trim().split(/\s+/).filter(Boolean);
  if (classTokens.length === 1) {
    return { type: 'element', ref: `.${classTokens[0]}` };
  }
  return { type: 'element', ref: element.tagName.toLowerCase() };
};

const deriveRelevantFiles = (
  request: ChangeRequest,
  element: ElementRef,
  staticEntry?: string,
): string[] => {
  const candidates = [
    ...(staticEntry ? [staticEntry] : []),
    ...request.sourceFiles,
    ...(element.filePaths ?? []),
  ];
  return Array.from(
    new Set(candidates.map((file) => file.trim()).filter(Boolean)),
  ).slice(0, MAX_RELEVANT_FILES);
};

const resolveSourceReferences = ({
  projectPath,
  files,
}: {
  projectPath: string;
  files: readonly string[];
}): string[] => {
  const paths = files.map((file) => {
    const selected = file.trim();
    if (!selected || selected.includes('\0')) {
      throw new AgentVariantsError(
        'SCHEMA_VALIDATION_FAILED',
        'Source references must be non-empty paths without null bytes.',
      );
    }
    return path.resolve(projectPath, selected);
  });
  return Array.from(new Set(paths)).slice(0, MAX_RELEVANT_FILES);
};

const resolveSourceVariantId = (request: ChangeRequest): string | undefined => {
  const batchTarget = request.target;
  if (batchTarget?.kind === 'variant') {
    return batchTarget.variantId;
  }
  const change = request.changes[0];
  if (change?.kind === 'comment' && change.target?.kind === 'variant') {
    return change.target.variantId;
  }
  return undefined;
};

const isZeroToOneRequest = (comment: CommentChangeItem): boolean =>
  comment.variantRequest?.mode === 'zero_to_one';

const hasRemoteReferences = (comment: CommentChangeItem): boolean =>
  Boolean(
    comment.variantRequest?.referencePages?.length ||
    comment.variantRequest?.referenceVideos?.length,
  );

const MAX_REFERENCE_PAGES = 3;
const MAX_REFERENCE_VIDEOS = 2;
const MAX_EVIDENCE_ROOT_VARIABLES = 24;

const summarizeEvidence = (
  url: string,
  evidence: BrowserEvidence,
): { note: string; bundleText: string } => {
  const fonts = evidence.fonts.slice(0, 6).join(', ') || 'none observed';
  const rootVariables = Object.entries(evidence.rootVariables).slice(
    0,
    MAX_EVIDENCE_ROOT_VARIABLES,
  );
  const tokens = rootVariables
    .map(([name, value]) => `${name}: ${value}`)
    .join('; ');
  const note = `Page ${url} (rendered, ${evidence.evidenceStatus}) — fonts: ${fonts}${
    tokens ? `; :root tokens: ${tokens}` : ''
  }`;
  const bundleText = [
    `# Rendered design evidence — ${url}`,
    `status: ${evidence.evidenceStatus}`,
    `fonts: ${fonts}`,
    rootVariables.length
      ? `:root variables:\n${rootVariables.map(([name, value]) => `  ${name}: ${value}`).join('\n')}`
      : ':root variables: none observed',
    Object.keys(evidence.elementStyles).length
      ? `element styles:\n${JSON.stringify(evidence.elementStyles, null, 2).slice(0, 6000)}`
      : '',
  ]
    .filter(Boolean)
    .join('\n\n');
  return { note, bundleText };
};

export class VariantGenerationService {
  private readonly recordGuidance?: VariantGenerationServiceOptions['recordGuidance'];
  private bridge: SessionBridgeService;
  private orchestrator: AgentVariantsOrchestrator;
  private staticPreviewRunner: StaticPreviewWorkItemRunner | undefined;
  private projectPath: string | undefined;
  private staticEntry: string | undefined;
  private readonly storage: ProjectStorage;
  private readonly onGeneratedProject?: (projectPath: string) => Promise<void>;
  private createSessionId: () => string;
  private executor?: WorkerExecutorService;
  private browserAgent: Pick<BrowserAgentClient, 'captureDesignEvidence'>;

  constructor(options: VariantGenerationServiceOptions) {
    this.recordGuidance = options.recordGuidance;
    this.storage = options.storage ?? new ProjectStorage();
    this.onGeneratedProject = options.onGeneratedProject;
    this.bridge = options.bridge;
    this.orchestrator = options.orchestrator;
    this.staticPreviewRunner = options.staticPreviewRunner;
    this.projectPath = options.projectPath;
    this.staticEntry = options.staticEntry;
    this.createSessionId = options.createSessionId ?? randomUUID;
    this.executor = options.executor;
    this.browserAgent = options.browserAgent ?? new BrowserAgentClient();
  }

  private async reportWorkerLease(
    initiator?: WorkItemInitiator,
    selection?: WorkerSelection,
  ): Promise<WorkerLeaseChoice> {
    const choice = await chooseWorkerLeaseOwner(this.executor, {
      ...(initiator ? { initiator } : {}),
      ...(selection ? { selection } : {}),
    });
    log.info(`variant workers: ${choice.summary}`);
    if (this.executor && !choice.runtime) {
      this.bridge.reportFeedback(`Directions will run via ${choice.summary}.`);
    }
    return choice;
  }

  async processVariantRequest(
    request: ChangeRequest,
  ): Promise<VariantRequestResult> {
    if (!isSingleVariantRequestBatch(request)) {
      this.bridge.reportFeedback(
        'Inline variants require one variant comment.',
      );
      return { success: false, error: 'Invalid inline variant request' };
    }

    const comment = request.changes[0] as CommentChangeItem;
    const assertContext = () => {
      assertGenerationGuidance(request);
      assertProfileAccount(comment);
    };
    assertContext();
    const beforeDispatch = (workItemIds: string[]) =>
      this.recordGuidance?.({ request, workItemIds });
    const count = comment.variantRequest?.count;
    const briefs = comment.variantRequest?.briefs;
    if (typeof count !== 'number') {
      this.bridge.reportFeedback('Inline variant request is missing a count.');
      return { success: false, error: 'Missing variant count' };
    }

    this.bridge.reportFeedback(`Starting ${count} inline variants.`);

    if (isZeroToOneRequest(comment)) {
      return this.processFreshVariantRequest({
        comment,
        sourceFiles: [
          ...request.sourceFiles,
          ...(comment.element.filePaths ?? []).filter(
            (file) => file.trim().length > 0,
          ),
        ],
        guidance: request.guidance ?? [],
        assertContext,
        beforeDispatch,
        count,
        requestId: request.agentRunId ?? request.traceId,
        ...(request.initiator ? { initiator: request.initiator } : {}),
        ...(request.workerSelection
          ? { workerSelection: request.workerSelection }
          : {}),
      });
    }

    try {
      const workerLease = await this.reportWorkerLease(
        request.initiator,
        request.workerSelection,
      );
      const uploaded = profileContextInputs(comment);
      const contextAssets = comment.variantRequest?.contextAssets ?? [];
      const contextProjectPath =
        this.projectPath ?? this.bridge.getProjectPath();
      const isRemoteReferencePreparationRequired = hasRemoteReferences(comment);
      let sessionId: string | undefined;
      let variantContext:
        ReturnType<typeof createVariantContextBundle> | undefined;
      if (
        (uploaded.userContextInputs.length > 0 ||
          uploaded.profileContextInputs.length > 0 ||
          contextAssets.length > 0 ||
          isRemoteReferencePreparationRequired) &&
        !contextProjectPath
      ) {
        const error = 'Inline variant context requires a project path';
        this.bridge.reportFeedback(`${error}.`);
        return { success: false, error };
      }
      const remoteReferencePromise = isRemoteReferencePreparationRequired
        ? this.prepareRemoteReferences(comment)
        : undefined;
      const sourceVariantId = resolveSourceVariantId(request);
      const referenceMode = profileReferenceMode(comment);
      const sourceTarget = request.target ?? comment.target;
      if (sourceTarget && comment.profileTrace) {
        const source = this.orchestrator.getVariantWorkItemInput(
          sourceTarget.sessionId,
          sourceTarget.variantId,
        );
        const inherited = retainedReferenceMetadata({
          source: source?.context,
          sourceReferenceMetadata: source?.references,
          profileReferenceMode: referenceMode,
        });
        if (inherited?.length)
          comment.profileTrace.inheritedReferences = inherited;
      }
      const relevantFiles = deriveRelevantFiles(
        request,
        comment.element,
        this.staticEntry,
      );
      const runLabel = comment.variantRequest?.runLabel;
      const remoteReferences = await remoteReferencePromise;
      assertContext();
      const userContextInputs = [
        ...uploaded.userContextInputs,
        ...(remoteReferences?.userContextInputs ?? []),
      ];
      if (
        (userContextInputs.length > 0 ||
          uploaded.profileContextInputs.length > 0 ||
          contextAssets.length > 0 ||
          Boolean(sourceVariantId)) &&
        contextProjectPath
      ) {
        sessionId = this.createSessionId();
        variantContext = createVariantContextBundle({
          sessionId,
          prompt: comment.instruction,
          workspaceRoot: contextProjectPath,
          dataDirectory: this.storage.resolve(contextProjectPath).dataDirectory,
          userContextInputs,
          profileContextInputs: uploaded.profileContextInputs,
          allowedRoots: [contextProjectPath],
          ...(contextAssets.length > 0 ? { contextAssets } : {}),
        });
      }
      const startResult = await this.orchestrator.startUnified({
        workerSelection: request.workerSelection,
        beforeDispatch,
        prompt: comment.instruction,
        assertContext,
        guidance: request.guidance ?? [],
        count,
        ...(runLabel ? { runLabel } : {}),
        ...(comment.variantRequest?.fidelity
          ? { fidelity: comment.variantRequest.fidelity }
          : {}),
        ...(briefs ? { briefs: briefs } : {}),
        target: deriveTarget(comment.element, this.staticEntry),
        ...(sessionId ? { sessionId } : {}),
        requestId: request.agentRunId ?? request.traceId,
        projectContext: {
          kind: 'existing',
          ...(contextProjectPath ? { projectPath: contextProjectPath } : {}),
          ...(variantContext ? { variantContext } : {}),
        },
        ...(relevantFiles.length > 0 ? { relevantFiles } : {}),
        leaseOwner: workerLease.leaseOwner,
        allowAccumulate: true,
        profileReferenceMode: referenceMode,
        ...(sourceVariantId ? { sourceVariantId } : {}),
      });

      this.orchestrator.setWorkerRuntime(
        startResult.sessionId,
        workerLease.summary,
      );
      const leasedItems = startResult.leasedWorkItems ?? [];
      this.bridge.reportFeedback(`Creating ${leasedItems.length} worktrees.`);
      if (leasedItems.length === 0) {
        const error = 'No inline variant work items were leased';
        this.bridge.reportFeedback(`${error}.`);
        await this.orchestrator
          .cancel({
            sessionId: startResult.sessionId,
            reason: error,
          })
          .catch((cancelError) => {
            log.warn('Inline variant session cancellation failed', cancelError);
          });
        return { success: false, error };
      }

      if (workerLease.runtime) {
        this.bridge.reportFeedback(
          `Rivet is building ${leasedItems.length} direction(s) with its own workers — watch status for progress.`,
        );
        void this.executor
          ?.run(
            startResult.sessionId,
            leasedItems.map((item) => item.id),
            startResult.leaseId
              ? { leaseId: startResult.leaseId, items: leasedItems }
              : undefined,
            workerLease.runtime,
            workerLease,
          )
          .catch((error: unknown) =>
            log.warn('worker executor run failed', error),
          );
      } else {
        this.bridge.reportFeedback(
          `Host agent work is ready for ${leasedItems.length} inline variants.`,
        );
      }
      return { success: true };
    } catch (error) {
      const message = errorMessage(error);
      log.error('Inline variant generation failed', error);
      this.bridge.reportFeedback(`Failed to start variants: ${message}`);
      this.bridge.reportFeedback('__RIVET_REFRESH_GIT__');
      return { success: false, error: message };
    }
  }

  private async prepareRemoteReferences(
    comment: CommentChangeItem,
  ): Promise<{ userContextInputs: RawUserContextInput[] }> {
    const userContextInputs: RawUserContextInput[] = [];
    const clipLabel = (label: string): string =>
      label.length <= 80 ? label : `${label.slice(0, 77)}...`;
    const pages = (comment.variantRequest?.referencePages ?? []).slice(
      0,
      MAX_REFERENCE_PAGES,
    );
    const videos = (comment.variantRequest?.referenceVideos ?? []).slice(
      0,
      MAX_REFERENCE_VIDEOS,
    );
    const [pageResults, videoResults] = await Promise.all([
      Promise.all(
        pages.map(async (page) => ({
          page,
          result: await this.browserAgent
            .captureDesignEvidence(page.url, { screenshot: true })
            .catch((error: unknown) => ({
              ok: false as const,
              available: true,
              reason: errorMessage(error),
            })),
        })),
      ),
      Promise.all(
        videos.map(async (video) => ({
          video,
          result: await extractVideoKeyframes(video.path),
        })),
      ),
    ]);

    for (const { page, result } of pageResults) {
      if (!result.ok) {
        log.warn(
          `reference page ${page.url} could not be rendered (${result.reason})`,
        );
        continue;
      }
      const { bundleText } = summarizeEvidence(page.url, result.evidence);
      userContextInputs.push({
        transport: 'text',
        content: bundleText.slice(0, 49_000),
        label: clipLabel(`Design evidence — ${page.url}`),
        userIntent: 'rendered page design evidence',
      });
      if (result.evidence.screenshotBase64) {
        userContextInputs.push({
          transport: 'upload',
          dataUrl: `data:image/png;base64,${result.evidence.screenshotBase64}`,
          label: clipLabel(`Reference page screenshot — ${page.url}`),
          userIntent: 'page reference',
        });
      }
    }

    for (const { video, result } of videoResults) {
      if (!result.ok) {
        log.warn(
          `video reference ${video.path} could not be sampled (${result.reason})`,
        );
        continue;
      }
      result.framePaths.forEach((framePath, index) => {
        try {
          const dataUrl = `data:image/png;base64,${fs
            .readFileSync(framePath)
            .toString('base64')}`;
          userContextInputs.push({
            transport: 'upload',
            dataUrl,
            label: clipLabel(
              `Video keyframe ${index + 1} of ${result.framePaths.length}${
                video.note ? ` — ${video.note}` : ''
              }`,
            ),
            userIntent: 'motion reference keyframe (chronological)',
          });
        } catch {}
      });
    }

    return { userContextInputs };
  }

  private async processFreshVariantRequest(args: {
    beforeDispatch: (workItemIds: string[]) => Promise<void> | void;
    guidance: GuidanceDocument[];
    assertContext: () => void;
    comment: CommentChangeItem;
    sourceFiles: string[];
    count: number;
    requestId?: string;
    initiator?: WorkItemInitiator;
    workerSelection?: WorkerSelection;
  }): Promise<VariantRequestResult> {
    const contextProjectPath = this.projectPath ?? this.bridge.getProjectPath();
    if (!contextProjectPath) {
      const error = 'Fresh variants require a project path';
      this.bridge.reportFeedback(`${error}.`);
      return { success: false, error };
    }

    const sourceReferences = resolveSourceReferences({
      projectPath: contextProjectPath,
      files: args.sourceFiles,
    });
    const resolvedWorkerLease = await this.reportWorkerLease(
      args.initiator,
      args.workerSelection,
    );
    const destination = deriveGeneratedDestination({
      prompt: args.comment.instruction,
      destinationParent: contextProjectPath,
    });
    if (!destination.ok) {
      this.bridge.reportFeedback(destination.message);
      return { success: false, error: destination.message };
    }

    await this.onGeneratedProject?.(destination.destinationPath);
    args.assertContext();

    const uploaded = profileContextInputs(args.comment);
    const remotePrepPromise = this.prepareRemoteReferences(args.comment);

    const suppliedBriefs = args.comment.variantRequest?.briefs;
    const defaults = fallbackDirections(args.comment.instruction, args.count);
    const briefs = suppliedBriefs?.length ? suppliedBriefs : defaults.briefs;
    const runLabel = args.comment.variantRequest?.runLabel ?? defaults.runLabel;
    const remotePrep = await remotePrepPromise;
    args.assertContext();

    const userContextInputs = [
      ...uploaded.userContextInputs,
      ...remotePrep.userContextInputs,
    ];
    let sessionId: string | undefined;
    let variantContext:
      ReturnType<typeof createVariantContextBundle> | undefined;
    const contextAssets = args.comment.variantRequest?.contextAssets ?? [];
    if (
      userContextInputs.length > 0 ||
      uploaded.profileContextInputs.length > 0 ||
      contextAssets.length > 0
    ) {
      sessionId = this.createSessionId();
      variantContext = createVariantContextBundle({
        sessionId,
        prompt: args.comment.instruction,
        workspaceRoot: destination.workspaceRoot,
        dataDirectory: this.storage.resolve(destination.workspaceRoot)
          .dataDirectory,
        userContextInputs,
        profileContextInputs: uploaded.profileContextInputs,
        allowedRoots: [destination.workspaceRoot],
        ...(contextAssets.length > 0 ? { contextAssets } : {}),
      });
    }

    const projectContext: ProjectContext = {
      kind: 'fresh',
      workspacePath: destination.destinationPath,
      workspaceRoot: destination.workspaceRoot,
      framework: 'vite',
      ...(variantContext ? { variantContext } : {}),
    };
    const workerLease =
      resolveRunPlanPolicy(projectContext).topology === 'static_preview'
        ? resolvedWorkerLease
        : ({
            leaseOwner: 'rivet-host-agent',
            summary: 'host path (vite lane)',
          } satisfies WorkerLeaseChoice);

    try {
      const startResult = await this.orchestrator.startUnified({
        beforeDispatch: args.beforeDispatch,
        workerSelection: args.workerSelection,
        prompt: args.comment.instruction,
        guidance: args.guidance,
        assertContext: args.assertContext,
        count: args.count,
        ...(runLabel ? { runLabel } : {}),
        ...(args.comment.variantRequest?.fidelity
          ? { fidelity: args.comment.variantRequest.fidelity }
          : {}),
        ...(briefs?.length ? { briefs } : {}),
        ...(sessionId ? { sessionId } : {}),
        requestId: args.requestId,
        projectContext,
        ...(sourceReferences.length > 0 ? { sourceReferences } : {}),
        leaseOwner: workerLease.leaseOwner,
        allowAccumulate: true,
      });
      this.orchestrator.setWorkerRuntime(
        startResult.sessionId,
        workerLease.summary,
      );
      const leasedItems = startResult.leasedWorkItems ?? [];
      if (workerLease.runtime && this.executor && leasedItems.length > 0) {
        this.bridge.reportFeedback(
          `Rivet is building ${leasedItems.length} direction(s) with its own workers — watch status for progress.`,
        );
        void this.executor
          .run(
            startResult.sessionId,
            leasedItems.map((item) => item.id),
            startResult.leaseId
              ? { leaseId: startResult.leaseId, items: leasedItems }
              : undefined,
            workerLease.runtime,
            workerLease,
          )
          .catch((error: unknown) =>
            log.warn('worker executor run failed', error),
          );
      } else {
        this.bridge.reportFeedback(
          `Host agent work is ready for ${startResult.variants.length} fresh variants.`,
        );
      }
      return { success: true };
    } catch (error) {
      const message = errorMessage(error);
      log.error('Fresh variant generation failed', error);
      this.bridge.reportFeedback(`Failed to start fresh variants: ${message}`);
      return { success: false, error: message };
    }
  }
}
